<?php require __DIR__.'/../config.php';$u=need('student');$id=(int)($_GET['id']??$_POST['id']??0);
// TAKE A CODE EXAM in the editor (like Visual Studio Code). Only students of the exam's class, only between the start time and the deadline.
// The time left = the time limit counted from when the student opened it, but never past the deadline.
$s=$pdo->prepare('SELECT * FROM coding_exams WHERE id=?');$s->execute([$id]);$x=$s->fetch();if(!$x)die('Exam not found');
$s=$pdo->prepare('SELECT * FROM exam_attempts WHERE exam_id=? AND student_id=?');$s->execute([$id,$u['id']]);$at=$s->fetch();
if($at&&$at['submitted_at']){header('Location: '.BASE.'Exam/exams.php');exit;}
if(!$at&&(!$x['class_id']||!in_class($x['class_id'],$u['id'])))blocked_page('Not your class','This code exam is for the students of another class. Join the class first on the <a href="Classes/classes.php">Classes</a> page.','Exam/exams.php');
