$code=(string)($_POST['code']??'');if($x['language']==='web'){$j=json_decode($code,true);$code=is_array($j['files']??null)?json_encode(['files'=>array_slice($j['files'],0,12,true)]):json_encode(['files'=>[]]);}
$pdo->prepare('UPDATE exam_attempts SET code=?,output=?,passed=?,submitted_at=NOW() WHERE id=? AND submitted_at IS NULL')->execute([mb_substr($code,0,300000),$out,$pass,$at['id']]);header('Location: '.BASE.'Exam/exams.php');exit;}
$st=work_state($x+['aid'=>$at?$at['id']:null]);
if($st[0]==='soon')blocked_page('Not open yet','This code exam opens on <b>'.e(when($x['opens_at'])).'</b> (<span class="cd" data-t="'.strtotime($x['opens_at']).'" data-pre="in "></span>). The page opens it by itself when the time comes.','Exam/exams.php');
if($st[0]==='missed')blocked_page('Missed','The deadline of this code exam was <b>'.e(when($x['due_at'])).'</b>. It can no longer be taken.','Exam/exams.php');
if(!$at){$pdo->prepare('INSERT INTO exam_attempts(exam_id,student_id,year_level) VALUES(?,?,?)')->execute([$id,$u['id'],$u['year_level']]);$s=$pdo->prepare('SELECT * FROM exam_attempts WHERE id=?');$s->execute([$pdo->lastInsertId()]);$at=$s->fetch();}
$left=$x['minutes']*60-max(0,time()-($at['started_at']?strtotime($at['started_at']):time()));if($due)$left=min($left,$due-time());$left=max(0,$left);
$files=$x['language']==='web'?exam_files('web',$x['starter']):[];
$prob='<p>'.nl2br(e($x['prompt'])).'</p><p><b>'.(int)$x['max_points'].' points</b> &middot; '.e(lname($x['language'])).'</p>'.($x['expected_output']!==''?'<p><b>Expected output</b></p><pre style="margin:0;padding:.5rem;background:#111;border-radius:6px;white-space:pre-wrap;font-size:.8rem">'.e($x['expected_output']).'</pre>':'').picture_html($x).($x['language']==='web'?'<p><small>Press + in EXPLORER to add a file. Forms and links to another file of the project open it in PREVIEW; PHP files run on the server.</small></p>':'');
head($x['title']);
echo '<div class="card" id="intro"><p>'.nl2br(e($x['prompt'])).'</p><p><b>'.e(lname($x['language'])).' &middot; '.(int)$x['minutes'].' minutes &middot; '.(int)$x['max_points'].' points</b>'.($due?' &middot; Deadline <b>'.e(when($x['due_at'])).'</b>':'').'</p>'.picture_html($x).'<p>You get <b>'.floor($left/60).' min '.($left%60).' s</b>. The timer runs from when you first opened this exam'.($due?' and stops at the deadline':'').'. When the time is up your code is submitted by itself.</p><p>You code in an editor like Visual Studio Code: files on the left, <b>Run</b> (or Ctrl+Enter), OUTPUT and PREVIEW on the right. Your code is also kept on this computer while you work.</p><p><small>Copy, paste, right-click and shortcuts are turned off. Leaving this tab or full screen is shown to your teacher, and leaving 3 times submits your exam. AI tips are off. After you submit, the lock is released.</small></p><button id="start" type="button">Start exam in full screen</button></div>';
echo '<form method="post" id="quiz" hidden data-what="exam" data-confirm="Are you sure you want to submit your exam? You cannot change your code after you submit." data-attempt="'.$at['id'].'" data-t="'.csrf().'" data-log="Exam/exam_event.php"><input type="hidden" name="t" value="'.csrf().'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="code" id="fc"><input type="hidden" name="output" id="fo">';
echo ide_html($x['title'],$prob,'<span class="ide-clock" id="clockbox">'.ico('clock').'<span id="clock"></span></span><button type="button" class="ide-run" data-ide-run>'.ico('play').'Run</button><button>Submit exam</button>',$x['language']==='web');
echo '</form><div id="warn" hidden></div>';
